#include <iostream>
#include <numeric>
#include <vector>

int sum_even(const std::vector<int>& values) {
    return std::accumulate(values.begin(), values.end(), 0, [](int total, int value) {
        return value % 2 == 0 ? total + value : total;
    });
}

int main() {
    const std::vector<int> values = { 3, 4, 6, 7 };
    std::cout << sum_even(values) << "\n";
    return 0;
}
